const ozSocialscience14Orta = <(String, String, List<String>, String)>[
  ('Bir belediye meclisinin aldığı bir karar ile Meclis\'in çıkardığı yasanın bir maddesi çelişirse hangisi geçerli olur?', 'Kanun hükmü', ['Belediye meclisi kararı', 'İkisi de eşit ağırlıkta uygulanır', 'Hangisinin daha yeni olduğuna bakılır'], 'Belediye meclisi kararı idari bir işlemdir ve kanunun altında yer alır; kanuna aykırı idari işlem hukuka aykırıdır.'),
  ('Kanunun yürürlüğe girmesi için Resmî Gazete\'de yayımlanması şartının amacı en iyi hangisidir?', 'Herkesin kuralları öğrenebilmesini sağlamak', ['Kanunun yargı denetiminden kurtulmasını sağlamak', 'Yayın tarihinden önceki olayları da kapsamasını sağlamak', 'Meclis tutanaklarını kalıcı kılmak'], 'Yayım, kuralların kamuya duyurulmasını sağlar; bilinmeyen bir kuralın bağlayıcı olması hukuki güvenlik ilkesiyle bağdaşmaz.'),
  ('Hukukta \'özel kanun genel kanunu kaldırır\' ilkesi hangi durumda işe yarar?', 'Aynı konuyu düzenleyen genel ve özel hükümler çatıştığında', ['Anayasa ile kanunun açıkça çatıştığı ve hangisinin üstün sayılacağının tartışıldığı durumlarda', 'İki ülkenin hukuku çatıştığında', 'Bir kanunun yayım tarihi belirsiz olduğunda'], 'Özel hüküm, genel hükme göre öncelikle uygulanır; böylece aynı konudaki genel kural özel kural karşısında geri çekilir.'),
  ('Kamu hukukuyla özel hukuku ayırmada kullanılan \'taraflardan birinin kamu gücü kullanması\' ölçütü hangisinde görülür?', 'Vergi borcunu tahsil eden idare ile mükellef arasındaki ilişkide', ['İki arkadaşın kendi aralarında karşılıklı borç para vermeyi kararlaştırmasında', 'Bir kişinin miras bırakması', 'Komşular arasındaki bahçe çiti anlaşmazlığında'], 'Vergi tahsilinde devlet egemenlik yetkisiyle hareket eder, taraflar eşit konumda değildir; bu da kamu hukuku ilişkisidir.'),
  ('Hukuk kurallarının zaman bakımından uygulanmasında \'geriye yürümezlik\' ilkesi ne anlama gelir?', 'Kanunun kural olarak yürürlüğe girdiği tarihten önceki olaylara uygulanmaması', ['Kanunun yalnızca geçmişteki olaylara, yürürlükten önce yapılan işlemlere uygulanması', 'Kanunun yürürlük tarihinden önce yayımlanması', 'Kanunun değiştirilememesi'], 'Hukuki güvenlik gereği yeni kanun kural olarak yürürlüğünden sonraki olay ve işlemlere uygulanır.'),
  ('TBMM Genel Kurulunda kanun tekliflerinin görüşülmesinde, teklifin tümü üzerindeki görüşmelerden sonra yapılan aşama hangisidir?', 'Maddelerin ayrı ayrı görüşülüp oylanması', ['Cumhurbaşkanının teklifi doğrudan değiştirmesi ve yeniden yazması', 'Danıştay\'ın teklifi onaylaması', 'Yargıtay\'dan görüş alınması'], 'Kanun teklifi önce tümü üzerinde görüşülür, ardından maddeler tek tek görüşülüp oylanır ve sonunda tümü oylanır.'),
  ('Bir kanunun Resmî Gazete\'de yayımlandığı tarihten sonra ilgili maddesinin \'yayımı tarihinden altı ay sonra yürürlüğe gireceği\' yazıyorsa bunun amacı ne olabilir?', 'Muhatapların yeni kurala uyum sağlaması için süre tanımak', ['Kanunun yargı denetimini engelleme ve kanunu iptalden koruma amacı', 'Kanunu Anayasa\'dan üstün kılmak', 'Kanunun geriye yürümesini sağlamak'], 'Yürürlük tarihinin ileriye bırakılması, uygulayıcıların ve kişilerin hazırlık yapmasına imkân verir.'),
  ('Meclis Genel Kurulu\'nda görüşmeler sırasında \'önerge\' veren milletvekilinin yapmak istediği şey en çok hangisidir?', 'Maddede değişiklik, çıkarma ya da ekleme önermek', ['Meclisin tatile girmesi için Cumhurbaşkanından izin istemek', 'Cumhurbaşkanını azletmek', 'Bütçeyi doğrudan kendisi sunmak'], 'Önergeler, görüşülmekte olan teklif veya maddede değişiklik teklif etmek amacıyla verilir.'),
  ('Kanunlar ile Cumhurbaşkanlığı kararnamelerinin ortak noktası olarak hangisi söylenebilir?', 'İkisi de Resmî Gazete\'de yayımlanarak yürürlüğe girer', ['İkisi de TBMM\'de oylanır', 'İkisi de Anayasa Mahkemesi\'nin denetimi dışında kalan düzenlemelerdir', 'İkisi de halk oylamasına bağlıdır'], 'Her iki düzenleme de Resmî Gazete\'de yayımlanır ve Anayasa Mahkemesi\'nin denetimine tabidir; kararname TBMM\'de oylanmaz.'),
  ('Kanun hükmünde kararnameler, 2017 değişikliğinden önce hangi organ tarafından çıkarılırdı?', 'Bakanlar Kurulu', ['Cumhurbaşkanı tek başına', 'Anayasa Mahkemesi', 'Yargıtay Genel Kurulu'], 'Eski Anayasa\'ya göre KHK\'ları, TBMM\'nin verdiği yetkiye dayanarak Bakanlar Kurulu çıkarırdı.'),
  ('İptal davası, kanunun Resmî Gazete\'de yayımından itibaren en geç ne kadar süre içinde açılmalıdır?', 'Altmış gün', ['On beş gün', 'Bir yıl', 'On yıl'], 'Anayasa m.151\'e göre iptal davası, kanunun yayımından itibaren altmış gün içinde açılabilir.'),
  ('Kanun yapım sürecinde Cumhurbaşkanının bir kanunu geri göndermesi hangi ilkenin bir örneğidir?', 'Yasama ve yürütme arasında karşılıklı denge ve denetim', ['Yargı bağımsızlığı ve mahkemelerin kararlarını yürütmeden koruması', 'Kuvvetler birliği', 'Halk egemenliği'], 'Geri gönderme yetkisi (veto benzeri) yürütmenin yasama üzerinde sınırlı denetimini gösterir; karşılıklı fren ve denge sistemidir.'),
  ('Bir milletvekilinin görev süresi içinde parti değiştirmesi, seçmen iradesi açısından hangi tartışmayı doğurur?', 'Temsil ilişkisi ve seçmene karşı sorumluluk tartışmasını', ['Vatandaşlığın kazanılması ve kaybı konusundaki tartışmayı', 'Seçim barajının hesaplanması konusundaki tartışmayı', 'Yerinden yönetim ve vesayet konusundaki tartışmayı'], 'Parti değiştirme, seçmenin oy verirken partiye duyduğu güveni ve milletvekilinin temsil ilişkisini gündeme getirir.'),
  ('Meclis tatilde iken olağanüstü toplanma kararı kimlerce verilebilir?', 'Cumhurbaşkanı veya Meclis Başkanı, üyelerin beşte biri talep ederse', ['Yalnızca Danıştay Başkanı, Meclis kararı olmaksızın', 'Bakanlar Kurulu kararıyla', 'Yargıtay Cumhuriyet Başsavcısı'], 'Anayasa m.93\'e göre Meclis tatilde veya ara vermede iken Cumhurbaşkanı ya da Meclis Başkanı olağanüstü toplantıya çağırabilir.'),
  ('Meclis soruşturması önergesinde amaç hangisidir?', 'Cumhurbaşkanı, yardımcıları ve bakanların görevleriyle ilgili suç iddialarını incelemek', ['Meclisin kendi bütçesini hazırlayıp Genel Kurulda onaylamak', 'Yargıçların maaşlarını belirlemek', 'Seçim barajını değiştirmek'], 'Meclis soruşturması, Cumhurbaşkanı, yardımcıları ve bakanlar hakkında görevleriyle ilgili suç iddialarında yapılan siyasi denetim yoludur.'),
  ('TBMM üyelerinin \'tam sayı\' ifadesi neyi gösterir?', 'Meclis üyelerinin fiilen mevcut olup olmadığına bakılmaksızın toplam üye sayısını', ['Yalnızca toplantıda hazır bulunan üyelerin sayısını belirtir', 'Yalnızca iktidar partisi üyelerini', 'Sadece grup başkanvekillerini'], 'Üye tamsayısı, Meclis\'in yasayla belirlenen toplam üye sayısıdır; oturumdaki sayı değildir.'),
  ('Milletvekillerinin Meclis içinde bir araya gelerek oluşturdukları \'Dostluk Grupları\' en çok hangi alanla ilgilidir?', 'Yabancı ülkelerin parlamentolarıyla ilişkiler', ['Seçim kampanyalarının planlanması ve parti örgütleri', 'Mahkemelerin kuruluşu', 'Bütçenin denetimi'], 'Parlamentolar arası dostluk grupları diğer ülkelerin parlamentolarıyla ikili ilişkileri geliştirmek üzere kurulur.'),
  ('Aşağıdaki ülkelerden hangisinde milletvekili seçimlerinde yaygın olarak basit çoğunluk sistemi kullanılmaktadır?', 'Birleşik Krallık', ['Hollanda', 'İsrail', 'Belçika'], 'Birleşik Krallık Avam Kamarası seçimlerinde tek turlu basit çoğunluk sistemi uygulanır; Hollanda ve İsrail yüksek derecede nispi temsil kullanır.'),
  ('Nispi temsil sisteminin en çok eleştirilen yönü hangisi olabilir?', 'Hükümet kurmayı güçleştiren parçalı meclis yapısına yol açabilmesi', ['Küçük partilerin hiçbir koşulda temsil edilememesi', 'Seçmen oylarının sonuca etki etmemesi', 'Yalnızca iki partinin seçilebilmesi'], 'Nispi sistemde meclis çok partili olur; bu da koalisyon kurmayı güçleştirebilir ve istikrarsızlığa yol açabilir.'),
  ('Seçim barajının koyulmasının başlıca gerekçelerinden biri hangisidir?', 'Meclisin aşırı parçalanmasını önleyerek istikrarlı hükümetler oluşmasını sağlamak', ['Küçük partilerin tamamen kapatılarak yalnız iki partinin kalması', 'Seçmenin oy hakkını azaltmak', 'Cumhurbaşkanının yetkisini artırmak'], 'Baraj, çok sayıda küçük partinin mecliste yer almasını sınırlandırarak yönetilebilir bir meclis hedefler.'),
  ('Bir ülkede seçimlerde bir parti oyların %38\'ini alıp meclisteki sandalyelerin %55\'ini kazanmışsa bu durum hangi sistemin bir sonucu olabilir?', 'Çoğunluk sistemi', ['Tam nispi temsil', 'Doğrudan demokrasi', 'Kura usulü'], 'Çoğunluk sistemlerinde oy oranı ile sandalye oranı arasında fark oluşabilir; nispi sistemde bu fark daha azdır.'),
  ('Seçmen kütüğünün (listesinin) askıya çıkarılarak vatandaşın hatalarını düzelttirmesine olanak tanınması hangi amaca hizmet eder?', 'Seçmenlerin kayıtlarının doğruluğunun denetlenmesi', ['Seçim barajının hesaplanması ve adayların belirlenmesi', 'Adayların tespit edilmesi', 'Oyların gizlenmesi'], 'Seçmen listelerinin ilanı, kişilerin kayıtlarını kontrol etmesini ve hataları düzelttirmesini sağlar.'),
  ('Bir derneğin kamuoyunu bilgilendirerek yeni bir çevre düzenlemesi için baskı oluşturması hangi demokratik işlevi yerine getirir?', 'Toplumsal talepleri siyasi karar alıcılara iletme', ['Mahkemelerin bağımsız kararlar vermesini sağlama', 'Bütçeyi kanunlaştırma', 'Seçim kurullarını oluşturma'], 'Sivil toplum örgütleri toplumsal sorunları gündeme getirerek karar vericilere iletir.'),
  ('Partilerin ideolojisine göre \'sol\' ve \'sağ\' ayrımının ortaya çıktığı tarihî olay hangisidir?', 'Fransız Devrimi sırasındaki meclis oturumları', ['Magna Carta\'nın İngiltere\'de imzalanması', 'Sanayi Devrimi\'nin başlaması', 'Westfalya Barışı'], 'Fransız Devrimi\'nde meclis başkanının sağındaki ve solundaki oturma düzeni, siyasal sağ ve sol kavramlarının kaynağı olmuştur.'),
  ('Maurice Duverger\'e göre nispi temsil sistemi hangi tür parti sistemiyle ilişkilidir?', 'Çok partili sistemle', ['Tek partili sistemle', 'Kesin iki partili sistemle', 'Partisiz sistemle'], 'Duverger yasalarına göre basit çoğunluk iki partililiğe, nispi temsil ise çok partililiğe yol açma eğilimindedir.'),
  ('Siyasi partilerin mali denetimini yapan Anayasa Mahkemesi, hangi kurumun yardımından yararlanır?', 'Sayıştay', ['Danıştay', 'Yargıtay', 'Merkez Bankası'], 'Anayasa m.69\'a göre partilerin mali denetimi Anayasa Mahkemesi tarafından yapılır; mahkeme Sayıştay\'ın yardımından yararlanır.'),
  ('Siyasi partilerin kapatılması için Anayasa Mahkemesi\'ne dava açma yetkisine sahip makam hangisidir?', 'Yargıtay Cumhuriyet Başsavcısı', ['Danıştay Başkanı', 'Türkiye Büyük Millet Meclisi Başkanı', 'Cumhurbaşkanı yardımcısı'], 'Anayasa m.69\'a göre parti kapatma davası Yargıtay Cumhuriyet Başsavcılığınca açılır.'),
  ('İdeolojik temelden çok seçmenin geniş kesimlerine hitap etmeyi hedefleyen parti türüne ne ad verilir?', 'Kitle (catch-all) partisi', ['Kadro partisi', 'Mezhep partisi', 'Gizli parti'], 'Kitle partileri geniş bir seçmen kitlesine hitap etmek için ideolojik sınırlarını esnetir.'),
